from copy import deepcopy


class TaskRunner:
    def __init__(self, retain_results=False):
        if not isinstance(retain_results, bool):
            raise TypeError("retain_results must be a boolean")
        self._retain_results = retain_results
        self._results = {}
        self._executed = []

    def execute(self, task_id, function, *args, **kwargs):
        if not isinstance(task_id, str) or not task_id:
            raise ValueError("task_id must be a non-empty string")
        if not callable(function):
            raise ValueError("function must be callable")
        if task_id in self._executed:
            raise ValueError("task_id was already executed")
        value = function(*args, **kwargs)
        self._executed.append(task_id)
        if not self._retain_results:
            self._results[task_id] = deepcopy(value)
        return value

    def result(self, task_id):
        if task_id not in self._results:
            raise LookupError(task_id)
        return deepcopy(self._results[task_id])

    def executed_ids(self):
        return list(self._executed)
```

